(* [comment removed for export] *)
Definition m2s_cells (m : mem) : Prop :=
  rw_cells asegs m 0x225d20 [C8 (Z_to_bv 64 0x244ab8); C8 (Z_to_bv 64 0x2457a8); C8 (Z_to_bv 64 0x2457b0); C8 (Z_to_bv 64 0x2457a0)]
